/**
 * @summary List all KYC submissions (admin)
 */
export const getListKycSubmissionsUrl = (params?: ListKycSubmissionsParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/admin/kyc?${stringifiedParams}`
    : `/api/admin/kyc`;
};

export const listKycSubmissions = async (
  params?: ListKycSubmissionsParams,
  options?: RequestInit,
): Promise<KycDocumentWithUser[]> => {
  return customFetch<KycDocumentWithUser[]>(getListKycSubmissionsUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getListKycSubmissionsQueryKey = (
  params?: ListKycSubmissionsParams,
) => {
  return [`/api/admin/kyc`, ...(params ? [params] : [])] as const;
};

export const getListKycSubmissionsQueryOptions = <
  TData = Awaited<ReturnType<typeof listKycSubmissions>>,
  TError = ErrorType<unknown>,
>(
  params?: ListKycSubmissionsParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof listKycSubmissions>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey =
    queryOptions?.queryKey ?? getListKycSubmissionsQueryKey(params);

  const queryFn: QueryFunction<
    Awaited<ReturnType<typeof listKycSubmissions>>
  > = ({ signal }) => listKycSubmissions(params, { signal, ...requestOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof listKycSubmissions>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type ListKycSubmissionsQueryResult = NonNullable<
  Awaited<ReturnType<typeof listKycSubmissions>>
>;
export type ListKycSubmissionsQueryError = ErrorType<unknown>;

